def category_hero_markup(slug,heading)
 info=CATEGORY_EXPERIENCES.fetch(slug);image,eyebrow,tagline,desc,*links=info
 nav=links.map{|l|text,url=l.split('|',2);a(url,text)}.join
 %(<header class="category-hero category-hero--#{h(image)}"><div class="category-hero-copy"><span class="eyebrow">#{h(eyebrow)}</span><h1>#{h(heading)}</h1><p class="category-tagline">#{h(tagline)}</p><p>#{h(desc)}</p><nav aria-label="Šīs lapas sadaļas">#{nav}</nav></div><div class="category-hero-art" aria-hidden="true"><span class="category-orbit"></span><img src="/assets/category-vector/#{h(image)}.svg?v={{ site.data.build.asset_version }}" width="320" height="260" alt=""><span class="category-art-caption">LATVIJA · KALENDĀRS365</span></div></header>)
end

def category_guide(title,items,source=nil,id='category-guide')
 %(<section class="category-guide" id="#{id}"><div><span class="eyebrow">ĪSS CEĻVEDIS</span><h2>#{h(title)}</h2>#{source ? '<p>'+source+'</p>' : ''}</div><div class="category-guide-steps">#{items.each_with_index.map{|(t,p),i|%(<article><b>#{format('%02d',i+1)}</b><div><h3>#{h(t)}</h3><p>#{h(p)}</p></div></article>)}.join}</div></section>)
end

def category_export_controls(kind,print=true)
 html=%(<div class="category-export"><label>Drukas dizains<select data-export-design><option value="1">Karmīna klasika</option><option value="6">Minimāls balts</option><option value="8">Darba ritms</option><option value="11">Skaidra nedēļa</option><option value="14">Redaktora stils</option></select></label><div class="category-export-buttons"><button type="button" data-category-export="#{kind}" data-format="pdf"><img src="/assets/file-pdf.svg" width="23" height="23" alt="">PDF <span aria-hidden="true">↓</span></button><button type="button" data-category-export="#{kind}" data-format="webp"><img src="/assets/file-image.svg" width="23" height="23" alt="">Attēls <span aria-hidden="true">↓</span></button>#{print ? '<button type="button" data-category-print>Drukāt</button>' : ''}</div><p class="category-export-status" role="status"></p></div>)
 if kind=='shift' && File.file?('downloads/mainas/manifest.json')
  options=JSON.parse(File.read('downloads/mainas/manifest.json')).fetch('items').map{|item|%(<option value="#{item['design']}">#{format('%02d',item['design'])} · #{h(item['title'])}</option>)}.join
  html.sub(/<select data-export-design>.*?<\/select>/m,%(<select data-export-design>#{options}</select>))
 else
  html
 end
end

