def category_astronomy_markup
 %(<section id="category-workspace" data-astronomy-explorer><div class="category-section-title"><div><span class="eyebrow">VIENOTS DEBESS NOTIKUMU PĀRSKATS</span><h2>Atrodi savu novērošanas vakaru</h2></div></div><form class="category-filter-bar"><label>Pilsēta<select name="city">#{CITIES.map{|c|"<option value=\"#{c['id']}\" #{c['id']=='riga' ? 'selected' : ''}>#{h(c['name'])}</option>"}.join}</select></label><label>Gads<select name="year">#{(2027..2030).map{|y|"<option>#{y}</option>"}.join}</select></label><label>Mēnesis<select name="month"><option value="0">Viss gads</option>#{MONTHS.each_with_index.map{|m,i|"<option value=\"#{i+1}\">#{h(m.capitalize)}</option>"}.join}</select></label><label>Notikums<select name="kind"><option value="all">Visi notikumi</option><option value="phase">Mēness fāzes</option><option value="solar">Saules aptumsumi</option><option value="lunar">Mēness aptumsumi</option><option value="season">Gadalaiku robežas</option><option value="meteor">Perseīdu vakari</option></select></label></form><div class="astronomy-feature" data-astronomy-feature></div><div class="category-result-bar"><p role="status" data-astronomy-count></p><div><button type="button" data-astronomy-ics>Saglabāt ICS ↓</button><button type="button" data-category-print>Drukāt</button></div></div><div class="astronomy-event-list" data-astronomy-results></div></section><section class="category-tools-grid" id="astronomy-tools">#{[['sunrise','/saullekts-saulriets/','Saules ceļš','Saullēkts, saulriets un dienas garums'],['moon-overview','/meness-kalendars/','Mēness kalendārs','Katras dienas apgaismojums un fāze'],['perseids','/perseidas/','Perseīdu naktis','Tumšās debesis un Mēness ietekme']].map{|photo,url,t,p|%(<a class="category-tool-card" href="#{url}"><img src="/assets/astronomy-events/#{photo}.svg" width="110" height="90" alt=""><span><strong>#{t}</strong><small>#{p}</small></span><b>↗</b></a>)}.join}</section><section class="category-source-panel" id="astronomy-method"><h2>Globāls notikums un vietējā redzamība ir divas dažādas lietas.</h2><p>Fāžu un gadalaiku brīži ņemti no USNO. Fāžu ilustrācijas rāda ziemeļu puslodes standarta skatu; tās nav konkrētā novērošanas brīža simulācija. Aptumsumu redzamība aprēķināta pilsētas centra koordinātām ar Astronomy Engine. Globālais maksimums nav automātiski redzams Latvijā. Mākoņi, ēkas un reljefs nav modelēti; Perseīdu naktis ir novērošanas plānošanas periodi, nevis garantēts maksimums.</p><p><a href="/avoti-un-metodika/">Aprēķinu avoti un metodika</a> · <a href="/pilsetas-un-fotografijas/#astronomy-event-art">Notikumu ilustrācijas</a> · <a href="https://aa.usno.navy.mil/data/">USNO dati</a> · <a href="https://github.com/cosinekitty/astronomy">Astronomy Engine</a></p></section>)
end

def category_body_markup(slug,body)
 case slug
 when 'menesa-kalendars','nedelas-kalendars'
  '{% include calendar-workbench.html %}'+(slug=='menesa-kalendars' ? category_month_library : category_week_library)+category_guide('Kalendārs, kas pielāgojas taviem plāniem.',[['Izvēlies periodu','Pārslēdz mēnesi, nedēļu vai dienu, nezaudējot savus notikumus.'],['Pieraksti svarīgo','Pievieno notikumu vai izvēlētās dienas piezīmi. Ieraksti paliek šajā pārlūkā.'],['Saglabā un izdrukā','Lejupielādē kalendāru un saglabā datu dublējumu, lai plānu varētu turpināt.']])
 when 'mainu-grafiks' then category_shift_markup
 when 'varda-dienas' then category_names_markup
 when 'svetki-un-tradicijas' then traditions_guide_markup(category_discovery_markup('traditions'))
 when 'visi-riki' then category_discovery_markup('tools')
 when 'meness-fazes' then category_phase_markup
 when 'gadalaiki' then category_seasons_markup
 when 'astronomiskais-kalendars' then category_astronomy_markup
 when 'gimenes-kalendars'
  body.sub('data-family-planner','id="category-workspace" data-family-planner').sub('<div class="organizer-two-col">','<div class="organizer-two-col" id="family-events">').sub('<h2>Maltīšu plāns</h2>','<h2 id="family-meals">Maltīšu plāns</h2>').sub('data-family-week-title','id="family-overview" data-family-week-title')+category_export_controls('family')+category_guide('Vairāk skaidrības kopīgajā nedēļā.',[['Atšķir cilvēkus','Katram ģimenes loceklim piešķir vārdu un krāsu. Kopīgs plāns var palikt bez viena atbildīgā.'],['Sasaisti ikdienu','Notikumi, mājas darbi un ēdienreizes palīdz saskatīt nedēļas noslodzi vienā vietā.'],['Paturi savu kopiju','Dublējums ietver locekļus, notikumus, maltītes un pirkumus; ICS der kalendāra notikumiem.']])
 when 'stundu-saraksts'
  body.sub('data-timetable-planner','id="category-workspace" data-timetable-planner').sub('data-class-lesson-form','id="timetable-editor" data-class-lesson-form').sub('data-class-task-form','id="timetable-tasks" data-class-task-form').sub('data-class-week-title','id="timetable-overview" data-class-week-title')+category_export_controls('school')
 when 'atvalinajuma-planotajs'
  vacation_planner_markup
 when 'saullekts-saulriets'
  %(<div id="category-workspace">#{body}</div><section class="sun-year-explorer" id="sun-year" data-sun-year><div class="category-section-title"><div><span class="eyebrow">GAISMAS GADS</span><h2>Salīdzini dienas garumu</h2></div><label>Gads<select name="year">#{(2027..2030).map{|y|"<option>#{y}</option>"}.join}</select></label></div><div data-sun-year-chart></div><div class="table-scroll" data-sun-year-table></div><button type="button" data-sun-year-csv>Gada tabula (CSV) ↓</button><p>Rādīts katra mēneša 21. datums izvēlētās pilsētas centrā. Aprēķins izmanto standarta horizontu; tā nav laikapstākļu prognoze.</p></section>)
 when 'meness-kalendars'
  %(<section class="lunar-quick-jump" id="category-workspace"><div><span class="eyebrow">TAVS MĒNESS MĒNESIS</span><h2>Uzreiz pie vajadzīgā datuma</h2></div><form data-lunar-jump><label>Gads<select name="year">#{(2027..2030).map{|y|"<option>#{y}</option>"}.join}</select></label><label>Mēnesis<select name="month">#{MONTHS.each_with_index.map{|m,i|"<option value=\"#{i+1}\">#{h(m.capitalize)}</option>"}.join}</select></label><button type="submit">Atvērt Mēness kalendāru ↗</button></form></section>#{body})+category_guide('Trīs veidi, kā lasīt Mēness kalendāru.',[['Dienas apgaismojums','Mēneša lapā vari atlasīt dienu un apskatīt aprēķināto apgaismojumu.'],['Precīza galvenā fāze','USNO norāda jaunmēness, pilnmēness un ceturkšņu brīžus; tie pārrēķināti Latvijas laikā.'],['Tava vieta','Mēness lēkts un riets ir atkarīgi no pilsētas. Atver novērošanas rīku vietējiem laikiem.']])
 else body
 end
end

def category_export_data
  articles=category_tradition_articles
  usage=articles.group_by{|article|article.fetch('photo').fetch('id')}.transform_values{|items|items.map{|item|item.slice('title','url')}}
  File.write('_data/tradition-photo-usage.json',JSON.pretty_generate(usage)+"\n")
  tools=tool_directory_catalog
  photo_sources=JSON.parse(File.read('_data/category-photos.json')).fetch('sources')
  season_photos=[CITIES.find{|c|c['id']=='iecava'}.fetch('photo')]+%w[summer autumn winter].map{|id|photo_sources.find{|p|p['id']==id}}
  File.write('assets/category-data.json',JSON.generate({names:DATA['names'],namesSource:CURRENT_NAMES.slice('checkedAt','edition','counts'),moon:DATA['moon'],seasons:DATA['seasons'],seasonPhotos:season_photos,seasonScenes:JSON.parse(File.read('_data/season-scenes.json')).fetch('scenes'),articles:articles,tools:tools,years:[2027,2028,2029,2030]}))
end
